document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".toggle-password").forEach(o=>{o.addEventListener("click",function(){const e=this.previousElementSibling;if(!e||e.tagName!=="INPUT")return;const t=e.type==="password"?"text":"password";e.type=t;const s=this.querySelector("i");t==="text"?(s.classList.remove("ph-eye"),s.classList.add("ph-eye-slash")):(s.classList.remove("ph-eye-slash"),s.classList.add("ph-eye"))})}),window.togglePassword=function(o,e){const t=document.getElementById(o),s=document.getElementById(e);!t||!s||(t.type==="password"?(t.type="text",s.classList.replace("ph-eye","ph-eye-slash")):(t.type="password",s.classList.replace("ph-eye-slash","ph-eye")))},document.querySelectorAll("form").forEach(o=>{o.addEventListener("submit",function(){const e=this.querySelector('button[type="submit"]');e&&(e.disabled=!0,e.innerHTML='<i class="ph-bold ph-spinner animate-spin"></i> Memproses...')})})});
